implementation:
#include <sys/socket.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

int receive_data(int fd, void __user *ubuf, size_t size, unsigned int flags, struct sockaddr __user *addr, int __user *addr_len) {
    struct msghdr msg = {0};
    struct iovec iov = {0};
    struct sock *sk = NULL;
    int ret = 0;

    if (!ubuf || !addr_len) {
        return -EINVAL;
    }

    iov.iov_base = ubuf;
    iov.iov_len = size;

    msg.msg_name = addr;
    msg.msg_namelen = sizeof(struct sockaddr);

    msg.msg_iov = &iov;
    msg.msg_iovlen = 1;

    sk = sockfd_lookup(fd, &ret);
    if (!sk) {
        return ret;
    }

    ret = sock_recvmsg(sk, &msg, flags, 0);
    if (ret < 0) {
        sockfd_put(sk);
        return ret;
    }

    if (addr && put_user(msg.msg_namelen, addr_len)) {
        ret = -EFAULT;
    }

    sockfd_put(sk);
    return ret;
}
